            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = pow(fact[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        // dp[i] represents the number of valid permutations of length i
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1] * (i - 1) % MOD;
            if (i > k) {
                dp[i] = (dp[i] + dp[i - k] * (i - 1) % MOD * invFact[k] % MOD * fact[k - 1] % MOD) % MOD;
